def _approve_sheets(lesson: Lesson) -> None:
    for pass_ in ('ink', 'colour'):
        lesson.approve('niccolo', pass_, f'sheets/niccolo-{pass_}.png', 'bart', '2026-11-26')
    lesson.cast['characters']['niccolo']['palette'] = {'cloak': RED}


# ── references ──────────────────────────────────────────────────────────────────────────────────

def test_a_sheet_bart_has_not_approved_stops_the_request(lesson, tmp_path):
    with pytest.raises(Refused, match='does not exist yet'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')


def test_a_sheet_that_changed_after_approval_needs_approval_again(lesson, tmp_path):
    _approve_sheets(lesson)
    _picture(lesson.media / 'sheets' / 'niccolo-ink.png', '#FAFAFA')
    with pytest.raises(Refused, match='changed after bart approved it'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')


def test_the_pack_holds_every_attachment_with_its_hash_in_attach_order(lesson, tmp_path):
    _approve_sheets(lesson)
    out = packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')
    manifest = json.loads((out / 'manifest.json').read_text())

    assert [a['role'] for a in manifest['attachments']] == ['blocking', 'identity', 'style']
    for item in manifest['attachments']:
        assert sha256(out / item['file']) == item['sha256']
        assert item['role'] == 'blocking' or item['sha256'] == sha256(Path(item['source'])), 'the approved file itself, byte for byte'
        assert packs.REFERENCE_MARK in item['file'], 'an ink request is a new picture: every input is a reference'
    prompt = (out / 'prompt.txt').read_text()
    assert 'Use the history-lines skill, pass 1 (ink) only.' in prompt
    assert 'Image 2 shows Niccolò' in prompt and '10 to 14%' in prompt
    assert 'Niccolò (image 2) is the rider in front' in prompt, 'each person is bound to a figure in each cell'
    assert 'walled village: small, far right. About 10% of the frame wide, centred 50% across.' in prompt, 'sizes come from the layout'
    assert (out / 'inputs.png').is_file()


def test_the_colour_pass_attaches_the_coloured_sheet_and_the_fixed_colours(lesson, tmp_path):
    _approve_sheets(lesson)
    ink = _board(tmp_path / 'ink.png', None)
    with pytest.raises(Refused, match='not the one recorded as approved'):
        packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'early', ink)

    ledger.add(lesson.media, {'event': 'ink-approved', 'board': 'plain-a', 'sha256': sha256(ink)})
    out = packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'pack', ink)
    files = [a['file'] for a in json.loads((out / 'manifest.json').read_text())['attachments']]

    assert packs.REFERENCE_MARK not in files[0], 'the ink board is the picture being coloured, not a reference'
    assert [f.split('-')[2].split('.')[0] for f in files[1:]] == ['identity', 'colours', 'style']
    prompt = (out / 'prompt.txt').read_text()
    assert f'cloak {RED}' in prompt and "row 1 Niccolò's cloak" in prompt


def test_nothing_is_sent_before_bart_saw_the_inputs_and_a_changed_pack_is_refused(lesson, tmp_path):
    _approve_sheets(lesson)
    out = packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')
    with pytest.raises(Refused, match='has not seen the exact inputs'):
        packs.sent(out, 'chatgpt', 'x', '2026-11-26', lesson.media)

    packs.seen(out, '2026-11-26')
    packs.sent(out, 'chatgpt', 'x', '2026-11-26', lesson.media)
    assert ledger.tally(lesson.media)['requests'] == 1

    (out / 'prompt.txt').write_text('something else')
    with pytest.raises(Refused, match='prompt.txt changed'):
        packs.seen(out, '2026-11-26')


# ── scene rules ─────────────────────────────────────────────────────────────────────────────────

def test_a_scene_without_accuracy_check_or_approved_layout_is_not_ready(lesson):
    scene = lesson.scene('plain')
    scene['accuracy'] = None
    scene['layout']['approved'] = None
    scene['boards'][0]['cells'][0]['who'] = ['niccolo', 'maffeo', 'niccolo', 'maffeo']
    problems = ' '.join(lesson.scene_problems(scene))
    assert 'accuracy' in problems and 'not approved by bart' in problems and 'at most 3' in problems


def test_two_characters_cannot_share_a_signature_colour(lesson):
    lesson.cast['characters']['maffeo']['signature'] = 'red'
    assert any('share the signature colour' in p for p in lesson.problems())


def test_the_same_failure_twice_stops_the_retries_until_the_approach_changes(lesson, tmp_path):
    _approve_sheets(lesson)
    for _ in range(2):
        ledger.add(lesson.media, {'event': 'rejected', 'board': 'plain-a', 'failures': ['colour-drift:niccolo']})
    with pytest.raises(Refused, match='already failed 2 times'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'again')
    packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'again', changed='sheet attached in pass 2')
    assert ledger.repeated(lesson.media, 'plain-a') == {}


# ── measuring the result ────────────────────────────────────────────────────────────────────────

def test_ink_weight_is_measured_per_cell(lesson, tmp_path):
    board = lesson.scene('plain')['boards'][0]
    assert verify.ink(board, _board(tmp_path / 'ok.png', None))['failures'] == []
    assert 'ink-weight' in verify.ink(board, _board(tmp_path / 'empty.png', None, lines=False))['failures']
    assert 'grid' in verify.ink(board, _board(tmp_path / 'gap.png', None, across_gap=True))['failures']
    assert 'ink-has-colour' in verify.ink(board, _board(tmp_path / 'col.png', RED))['failures']


def test_a_cloak_in_the_wrong_colour_fails_and_the_right_one_passes(lesson, tmp_path):
    _approve_sheets(lesson)
    board = lesson.scene('plain')['boards'][0]
    ink = _board(tmp_path / 'ink.png', None)

    assert verify.coloured(lesson, board, ink, _board(tmp_path / 'red.png', RED))['failures'] == []
    brown = verify.coloured(lesson, board, ink, _board(tmp_path / 'brown.png', BROWN))
    assert brown['failures'] == ['colour-drift:niccolo']
    slightly_off = verify.coloured(lesson, board, ink, _board(tmp_path / 'off.png', '#B8604F'))
    assert slightly_off['failures'] == [], 'a small step inside the limit passes'


def test_someone_elses_reserved_colour_in_the_shot_is_pointed_out(lesson, tmp_path):
    _approve_sheets(lesson)
    board = lesson.scene('plain')['boards'][0]
    image = Image.open(_board(tmp_path / 'red.png', RED))
    ImageDraw.Draw(image).rectangle([500, 150, 650, 330], fill=BLUE)
    image.save(tmp_path / 'blue.png')
    notes = verify.coloured(lesson, board, _board(tmp_path / 'ink.png', None), tmp_path / 'blue.png')['notes']
    assert any("Maffeo's cloak colour" in n and 'not in this shot' in n for n in notes)


def test_a_colour_pass_that_moved_the_drawing_is_caught(lesson, tmp_path):
    _approve_sheets(lesson)
    board = lesson.scene('plain')['boards'][0]
    report = verify.coloured(lesson, board, _board(tmp_path / 'ink.png', None), _board(tmp_path / 'moved.png', RED, shift=12))
    assert 'ink-redrawn' in report['failures']


def test_two_named_people_in_a_cell_need_a_place_each_and_marked_regions_to_be_scored(lesson, tmp_path):
    _approve_sheets(lesson)
    scene = lesson.scene('plain')
    scene['boards'][0]['cells'][0]['who'] = ['niccolo', 'maffeo']
    assert any('"where" must say which figure' in p for p in lesson.scene_problems(scene))

    board = scene['boards'][0]
    ink, col = _board(tmp_path / 'ink.png', None), _board(tmp_path / 'red.png', RED)
    report = verify.coloured(lesson, board, ink, col)
    assert report['failures'] == [] and any('not scored' in n for n in report['notes'])
    marked = verify.coloured(lesson, board, ink, col, {'1': {'niccolo': [0.3, 0.2, 0.6, 0.8], 'maffeo': [0.6, 0.2, 0.9, 0.8]}})
    assert marked['failures'] == ['colour-missing:maffeo'], 'the red is there, but not on Maffeo'


def test_a_landmark_keeps_its_size_until_the_camera_moves_closer():
    far = boards.project({'at': [0, 0], 'looks_at': [100, 0]}, [3000, 0], 200)
    near = boards.project({'at': [2800, 0], 'looks_at': [3000, 0]}, [3000, 0], 200)
    assert far['width'] < 0.1 < near['width'] and far['x'] == 0.5
    assert boards.project({'at': [0, 0], 'looks_at': [100, 0]}, [-50, 0]) is None, 'behind the camera'
    assert boards.project({'at': [0, 0], 'looks_at': [0, 100]}, [50, 100])['x'] > 0.5, 'east is right when looking north'


def test_the_palette_is_sampled_from_the_approved_sheet(lesson):
    _approve_sheets(lesson)
    assert colour.delta(colour.hex_rgb(colour.sample(colour.load(lesson.sheet('niccolo', 'colour')))), colour.hex_rgb(RED)) < 2


def test_the_reviewers_marks_pass_at_ninety_and_an_instant_no_always_rejects():
    full = dict(verify.SCORE)
    assert verify.score(full, [])['passes']
    assert not verify.score(full, ['wrong character'])['passes']
    assert not verify.score({**full, 'face': 5}, [])['passes']


# ── from board to keyframes ─────────────────────────────────────────────────────────────────────

def test_only_the_board_bart_approved_is_cut_and_the_crops_are_recorded(lesson, tmp_path, monkeypatch):
    _approve_sheets(lesson)
    write(lesson.cast_file, lesson.cast)
    monkeypatch.setattr(shots, 'Lesson', lambda slug: Lesson(slug, tmp_path / 'shots', tmp_path / 'media', tmp_path / 'style'))
    ink, col = _board(tmp_path / 'ink.png', None), _board(tmp_path / 'col.png', RED)
    marks = tmp_path / 'marks.json'
    write(marks, {'marks': dict(verify.SCORE), 'instant_no': []})

    assert shots.main(['cut', 'test', 'plain', 'plain-a', str(col)]) == 2
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'ink', str(ink), '--by', 'claude']) == 2, 'two reviewers'
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'ink', str(ink), '--by', 'claude,chatgpt']) == 0
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'colour', str(col), '--ink', str(ink), '--by', 'claude,chatgpt', '--marks', str(marks)]) == 2
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'colour', str(col), '--ink', str(ink), '--by', 'claude,chatgpt,bart', '--marks', str(marks)]) == 0
    assert shots.main(['cut', 'test', 'plain', 'plain-a', str(col)]) == 0

    folder = lesson.media / 'stills' / 'plain-a'
    crops = json.loads((folder / 'crops.json').read_text())
    assert [c['shot'] for c in crops['crops']] == [1, 2, 3, 4] and crops['upscale'] == 'lanczos'
    assert Image.open(folder / 'plain-a-shot-01.png').size == (1920, 1080)
    assert ledger.tally(lesson.media)['cells_accepted'] == 4


def test_the_layout_map_and_grid_are_drawn_by_code(lesson):
    scene = lesson.scene('plain')
    assert boards.layout_map(scene, scene['boards'][0]).width == 1600
    assert boards.cells(3840, 2160, 2, 2)[3] == (1922, 1082, 3840, 2160)
